// EncodeOrc writes the value to w in the Orc binary format.
func (s Schematic) EncodeOrc(w *orc.Writer) error {
	w.Write(s.Key[:])
	w.String(s.Name)
	w.Bool(s.Snapshot)
	w.Bool(s.Nodes != nil)
	if s.Nodes != nil {
		w.Uint32(uint32(len(s.Nodes)))
		for i := range s.Nodes {
			if err := s.Nodes[i].EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	w.Bool(s.Edges != nil)
	if s.Edges != nil {
		w.Uint32(uint32(len(s.Edges)))
		for i := range s.Edges {
			if err := s.Edges[i].EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	w.Bool(s.Configs != nil)
	if s.Configs != nil {
		w.Uint32(uint32(len(s.Configs)))
		for key, val := range s.Configs {
			w.String(key)
			if err := val.EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	return nil
}

// DecodeOrc reads the value from r in the Orc binary format.
func (s *Schematic) DecodeOrc(r *orc.Reader) error {
	var err error
	if _, err := r.Read(s.Key[:]); err != nil {
		return err
	}
	if s.Name, err = r.String(); err != nil {
		return err
	}
	if s.Snapshot, err = r.Bool(); err != nil {
		return err
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Nodes = make([]Node, n)
			for i := range s.Nodes {
				if err = s.Nodes[i].DecodeOrc(r); err != nil {
					return err
				}
			}
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Edges = make([]Edge, n)
			for i := range s.Edges {
				if err = s.Edges[i].DecodeOrc(r); err != nil {
					return err
				}
			}
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Configs = make(map[string]ElementConfig, n)
			for range n {
				var key string
				var val ElementConfig
				if key, err = r.String(); err != nil {
					return err
				}
				if err = val.DecodeOrc(r); err != nil {
					return err
				}
				s.Configs[key] = val
			}
		}
	}
	return nil
}

// EncodeOrc writes the value to w in the Orc binary format.
func (sec SegmentedEdgeConfig) EncodeOrc(w *orc.Writer) error {
	if sec.StrokeColor != nil {
		w.Bool(true)
		if err := sec.StrokeColor.EncodeOrc(w); err != nil {
			return err
		}
	} else {
		w.Bool(false)
	}
	if sec.StrokeWidth != nil {
		w.Bool(true)
		w.Float64(float64(*sec.StrokeWidth))
	} else {
		w.Bool(false)
	}
	w.Bool(sec.Segments != nil)
	if sec.Segments != nil {
		w.Uint32(uint32(len(sec.Segments)))
		for i := range sec.Segments {
			if err := sec.Segments[i].EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	return nil
}

// DecodeOrc reads the value from r in the Orc binary format.
func (sec *SegmentedEdgeConfig) DecodeOrc(r *orc.Reader) error {
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			var hv color.Color
			if err = hv.DecodeOrc(r); err != nil {
				return err
			}
			sec.StrokeColor = &hv
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			var hv float64
			if hv, err = r.Float64(); err != nil {
				return err
			}
			sec.StrokeWidth = &hv
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			sec.Segments = make([]Segment, n)
			for i := range sec.Segments {
				if err = sec.Segments[i].DecodeOrc(r); err != nil {
					return err
				}
			}
		}
	}
	return nil
}
